import type { CardInfo, Deck, FormatData, FormatId, SeasonWithDecks } from './types'
import { STANDARD_SEASONS } from './standard/seasons'

type SeasonFile = { season: string; decks: Deck[] }

// Generated by scripts/pipeline/build.py — one JSON file per season.
const standardDeckFiles = import.meta.glob<SeasonFile>('./standard/decks/*.json', { import: 'default' })
const standardCards = () => import('./standard/cards.json').then((m) => m.default as unknown as Record<string, CardInfo>)

const cache = new Map<FormatId, Promise<FormatData>>()

async function loadStandard(): Promise<FormatData> {
  const [files, cards] = await Promise.all([
    Promise.all(Object.values(standardDeckFiles).map((load) => load())),
    standardCards(),
  ])
  const bySeason = new Map(files.map((f) => [f.season, f.decks]))
  const seasons: SeasonWithDecks[] = STANDARD_SEASONS.map((s, i) => ({
    ...s,
    end: STANDARD_SEASONS[i + 1]?.start,
    decks: (bySeason.get(s.id) ?? []).slice().sort((a, b) => a.tier - b.tier || b.stats.share - a.stats.share),
  })).filter((s) => s.decks.length > 0)
  return { seasons, cards }
}

export function loadFormat(format: FormatId): Promise<FormatData> | null {
  if (format !== 'standard') return null
  if (!cache.has(format)) cache.set(format, loadStandard())
  return cache.get(format)!
}

export function findDeck(data: FormatData, id: string): { deck: Deck; season: SeasonWithDecks } | undefined {
  for (const season of data.seasons) {
    const deck = season.decks.find((d) => d.id === id)
    if (deck) return { deck, season }
  }
  return undefined
}
